  helpSum_admin_stock:
    'View and adjust stock by store or HQ warehouse. The HQ daily in/out tab shows S&J inbound, store outbound, balance, and invoices.',
  helpHow_admin_stock:
    '① Stock list: pick store and as-of date, then search. Stock value uses two decimal places (0.01 baht), same basis as P&L inventory. During the due window (month-end −2 ~ next month +5) a banner appears. Managers can adjust stock. Adjustments are saved on the selected as-of date—for month-end, set that date then Adjust. Links from Store operations pre-fill store and month-end.\n② Reorder assist: usage window and suggested qty (does not auto-order).\n③ HQ daily in/out (office): matrix by period, warehouse, store, and view mode; drill to outbound history or invoice print.\n④ Export XLSX in Daily Stock Report layout.',
  helpSum_admin_outbound:
    'Ship from HQ warehouse to stores or sales accounts. Force outbound items confirmed together (same date, destination, Reference No.) share one IVF sheet; order outbound stays one IV per order. Tax invoices, e-Tax, and billing use delivered (including partial) rows only; history totals split billable vs all outbound.',
  helpHow_admin_outbound:
    '① Outbound Entry: set dates, destination, and required Reference No., add items, then Confirm. Matching date/destination/reference print as one invoice.\n② History: search the period, then print Invoice, delete, or export Excel. The green total is billable (delivered) VAT; the gray line is all warehouse outbound including in transit. In-transit rows cannot print tax invoices or e-Tax. Expand a Force row to see grouped items.\n③ Some tabs may be hidden by role.',
  helpSum_admin_notices:
    'Compose and send staff notices, review history and unread lists, and manage auto alerts (work log, month-end stock take).',
  helpHow_admin_notices:
    '① New notice: pick targets, preview, then send.\n② Sent history: read rates, reminders, limited edits.\n③ Unread: aggregate misses and allowance exclusion.\n④ Auto alerts: work log and month-end stock take (due start + day after month-end, missing stores only), plus “Add recurring notice”.',
  stockReorderIntro:
    'HQ (Office / inbound warehouse): sums Outbound + ForceOutbound from HQ. Stores: Usage (manual usage confirm) only. Suggested reorder = max(0, period consumption + safety stock − on hand). Does not create purchase orders automatically.',
