  hrPolicyListLoadError: 'Could not load the policy list. Refresh and try again.',
  helpSum_admin_hr_policies:
    'Register HR policies and set audiences (head office, stores, or individuals). Review content and read status in the list; deploy via notice when ready.',
  helpHow_admin_hr_policies:
    '① Enter title, attachment/body, and audience (all / head office / stores / individuals), then save. Saved policies appear immediately for the target staff.\n② Use list filters, “View registered content”, and read details to verify.\n③ Use “Targets & deploy (notice)” to send a notice. Deactivate drafts from the list if needed.',
  helpSum_admin_hr:
    'HR hub — pending leave/attendance (sidebar badges count only unapproved GPS/forced clock-out and recent leave), this week’s HR events, and quick links to payroll, staff, and policies.',
  helpHow_admin_hr:
    '① KPI and sidebar badges count only items nobody has approved yet (attendance: GPS/forced; leave: recent leave dates).\n② Use each card’s shortcut to open Leave, Attendance, Calendar, or Payroll.\n③ Use the sub-navigation bar for Employees, Policies, Calendar, Attendance, Leave, and Payroll.',
  helpSum_admin_attendance:
    'Review and approve clock-in/out, adjust late/early/OT, view today’s live status, and browse or edit weekly schedules in one place. Sidebar badges show only unapproved GPS/forced items.',
  helpHow_admin_attendance:
    '① Records & approval: filter by period, store, employee, and status, then approve or adjust. Overnight (22:00–08:00) clock-out until 08:59 next morning stays on the clock-in date.\n② Today live: pick a store, then tap Search to see hour-by-hour work/break dots. On a phone, swipe the table up, down, or sideways.\n③ Schedule view / edit: review or edit weekly rosters. Batch break start follows the grid (default 06:00–31:00; after midnight use 24:00+, and 07:00 next morning is 31:00). Save validates same-day duplicate staff first and does not clear the week on validation errors.\n④ Sidebar counts are GPS/forced unapproved only; late/OT/early adjustments are handled here by date filter.\n⑤ Help tab: read approval, adjustment, and OT rules.\n⑥ Next to break minutes, planned vs actual break (start–end) is shown. A start outside the planned window is red. Schedule view and edit show each person’s last editor and time; open that line to see what changed that week.',
  helpSum_admin_leave:
    'Approve or reject leave requests and review annual/sick/unpaid usage and balances by period. Use the Approvers tab for global and per-store approvers. Stats default to current staff. Sidebar badges count only recent unapproved leave dates.',
  helpHow_admin_leave:
    '① Approval: review certificates, then approve or reject pending requests.\n② Stats: query usage and remaining leave by period and store. Default list is current staff; choose Resigned or All to include former employees.\n③ Approvers: set global approvers (all stores) and per-store approvers. Once a store has any designated approver, only that list (+ global + Director) can approve. Stores with none keep manager/franchisee fallback.\n④ Payroll may deep-link here by month.\n⑤ Sidebar badges count pending leave from the last 30 leave-days through future dates only.',
  helpSum_admin_hr_calendar:
    'View birthdays, hire dates, work anniversaries, and resignations on a monthly calendar and list.',
  helpHow_admin_hr_calendar:
    '① Filter by month, store, and event type.\n② Click a calendar chip or list row to open the employee profile.\n③ Use birthdays and anniversaries alongside store operations.',
  helpSum_admin_payroll:
    'Calculate and save payroll, view statements, salary change history, holidays, rules, and help in one place.',
  helpHow_admin_payroll:
    '① Payroll calc: pick the month (work period and pay date show below) → Calculate → review → Save to DB. Change the cycle in Payroll rules (default: 1st–last day, 5th of next month). P&L salary follows this month.\n② Records: view saved payroll (name and nickname), notify staff, export Excel.\n③ Help tab: late, early, OT, and holiday rules.\n④ Confirming office (HQ) payroll posts one store/month total to Expense Management—not per-employee lines (individual detail stays in Payroll for office payroll managers).',
  adminHrCalendar: 'HR calendar',
  hrCalHint:
    'Shows birthdays, hire milestones (Year 1, 2, 3…), hire dates in the join year, and resignations by month. Labels use nickname; hover a cell for the full text.',
