  adminAccountingPurchaseOrderTitle: 'PO management',
  adminAccountingPurchaseOrderSub:
    'Bill stores for royalty, delivery GP, Grab GP, etc. as POs. Set rates under [Billing rates], then add lines from POS sales on the HQ PO tab. For inter-store billing (e.g. Silom→The Street), pick the issuing store in the Issuing store dropdown. Edit a Draft from history (pencil) before approving. If decimals differ from FlowAccount, use the pencil icon on the totals to override subtotal, VAT, and total.',
