  adminBalanceSheet: 'Balance Sheet',
  adminFinancialStatements: 'Management accounts',
  helpSum_admin_financial_statements:
    'Management accounts for running the stores. Amounts may differ from the tax books. View P&L, balance sheet, and margin by store and period. The balance sheet includes borrowings (2150) and loans receivable (1150). Salary (5310) posts to the payroll month, not the pay date. Approved accounting POs (royalty, delivery GP, Grab GP) post to store expenses and HQ (issuer) sales; amounts follow the VAT included/excluded toggle (PO total vs subtotal). VAT-inclusive view adds PP.30 remittance as an expense in the tax month (excluded view and PND stay out).',
  helpHow_admin_financial_statements:
    '① Choose store and start/end month, then search. Changing month or store alone does not reload income, balance, reconcile, or margin until you search again.\n② Switching VAT included/excluded adjusts sales, purchases, inventory, and approved franchise-billing PO amounts together. Amounts show two decimal places (0.01 baht). Inclusive view only adds PP.30 remittance as expense in the tax month (not the bank pay date).\n③ Royalty / delivery / Grab GP hit the P&L only after the accounting PO is Approved (Draft and platform fee 5528 are separate).\n④ Enter and save manual sales / beginning inventory on a single-month query; multi-month view applies each month’s saved values.\n⑤ Search filters and results stay when you switch menus or sub-tabs.\n⑥ Payroll hits that month’s P&L, not the pay date. Confirmed payroll excludes salary-like bank/petty cash to avoid double counting.',
