  pL_vatDisplayExcludedNote:
    'VAT exclusive view: POS uses total−vat; logistics, inbound, and inventory use supply amounts per item tax_type. Bank, petty, and fee accruals subtract only stored vat_amount (or linked expense accrual VAT); if missing, cash paid stays. No 7% estimation. PP.30 remittance and PND are not expenses in this view. Use this to reconcile with PP30 and outbound management.',
